export const MONTHS=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
export const WEEKDAYS=['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
export const clone=x=>JSON.parse(JSON.stringify(x));
export const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
export const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
export function dateKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
export function parseDate(k){return new Date(Number(k.slice(0,4)),Number(k.slice(5,7))-1,Number(k.slice(8,10)),12);}
export function todayKey(){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Monterrey',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
export function weekStart(k){const d=parseDate(k);d.setDate(d.getDate()-d.getDay());return dateKey(d);}
export function weekDates(k){const d=parseDate(weekStart(k));return Array.from({length:7},(_,i)=>{const t=new Date(d);t.setDate(d.getDate()+i);return dateKey(t);});}
export function monthWeeks(y,m){const first=new Date(y,m,1,12);const last=new Date(y,m+1,0,12);const out=[];for(let d=parseDate(weekStart(dateKey(first)));d<=last;d.setDate(d.getDate()+7))out.push(weekDates(dateKey(d)));return out;}
export function monthKey(y,m){return `${y}-${String(m+1).padStart(2,'0')}`;}
export function defaultDay(k){const dow=parseDate(k).getDay();const times=dow===0?['08:00','12:00','17:00','19:00']:dow>=1&&dow<=5?['19:00']:[];return {date:k,note:'',reviewed:false,masses:times.map((time,i)=>({id:`${k}-${i}`,time,place:dow===0&&i===2?'Capilla La Inmaculada':'Parroquia',title:'',note:'',personIds:[]}))};}
export function emptyState(){return {schema:1,entities:{},pending:{},history:[],conflicts:[],lastSync:null};}
export const recordKey=(type,id)=>`${type}:${id}`;
export function list(s,type){return Object.values(s.entities).filter(e=>e.type===type&&!e.deleted).map(e=>e.data);}
export function getDay(s,k){return s.entities[recordKey('day',k)]?.data||defaultDay(k);}
export function change(s,type,id,data,label){const key=recordKey(type,id);const before=s.entities[key];const record={type,id,version:before?.version||null,data:clone(data),deleted:false};const pending=s.pending[key];s.pending[key]={...record,baseVersion:pending?pending.baseVersion:before?.version||null,baseData:pending?pending.baseData:before?clone(before.data):null,mutationId:uid()};s.entities[key]=record;s.history.unshift({id:uid(),at:new Date().toISOString(),label,type,entityId:id,before:before?clone(before.data):null,after:clone(data)});s.history=s.history.slice(0,800);return record;}
export function createMonth(s,y,m){const key=monthKey(y,m);if(s.entities[recordKey('month',key)])return false;change(s,'month',key,{key,year:y,month:m},`Crear ${MONTHS[m]} ${y}`);for(let i=1;i<=new Date(y,m+1,0).getDate();i++){const k=dateKey(new Date(y,m,i,12));if(!s.entities[recordKey('day',k)])change(s,'day',k,defaultDay(k),`Preparar ${k}`);}return true;}
export function assign(day,massId,personId){const mass=day.masses.find(m=>m.id===massId);if(!mass)throw Error('Misa no encontrada');if(!mass.personIds.includes(personId))mass.personIds.push(personId);}
export function weekSummary(s,k){const dates=weekDates(k);const active=list(s,'person').filter(p=>p.active!==false&&!p.mergedInto);const counts=Object.fromEntries(active.map(p=>[p.id,0]));let emptyMasses=0;const missingDays=[];for(const key of dates){const rec=s.entities[recordKey('day',key)];if(!rec){missingDays.push(key);continue;}for(const m of rec.data.masses){if(!m.personIds.length)emptyMasses++;for(const id of new Set(m.personIds))if(id in counts)counts[id]++;}}return {dates,counts,unassigned:active.filter(p=>!counts[p.id]),active,emptyMasses,missingDays,reviewed:dates.filter(k=>s.entities[recordKey('day',k)]?.data.reviewed).length};}
function isUntouchedScaffold(e){if(!e||e.deleted)return false;const d=e.data;if(e.type==='month')return d?.key===e.id&&monthKey(d.year,d.month)===e.id;if(e.type!=='day'||d?.date!==e.id||d.reviewed||d.note||!Array.isArray(d.masses))return false;const usual=defaultDay(e.id).masses;return d.masses.length===0||d.masses.length===usual.length&&d.masses.every((m,i)=>m.id===usual[i].id&&m.time===usual[i].time&&m.place===usual[i].place&&!m.title&&!m.note&&Array.isArray(m.personIds)&&!m.personIds.length);}
export function mergeResponse(s,response,sent={}){for(const [key,e] of Object.entries(s.entities)){const canonical=e.type==='day'?e.data.date:e.type==='month'?e.data.key:e.id;if(e.id!==canonical&&!s.pending[key])delete s.entities[key];}const remote=new Map(response.entities.map(e=>[recordKey(e.type,e.id),e]));const adopted=new Set();for(const [key,e] of remote){const pending=s.pending[key];if(pending&&!pending.baseVersion&&!pending.baseData&&isUntouchedScaffold(pending)&&isUntouchedScaffold(s.entities[key])){delete s.pending[key];s.entities[key]=clone(e);adopted.add(key);}}const ack=new Map((response.ack||[]).map(x=>[x.key,x]));for(const [key,a] of ack){if(!s.pending[key])continue;if(s.pending[key].mutationId===sent[key]?.mutationId)delete s.pending[key];else s.pending[key].baseVersion=a.version;}
 for(const [key,e] of remote){if(!s.pending[key])s.entities[key]=clone(e);else if(ack.has(key)){s.entities[key].version=e.version;s.pending[key].baseData=clone(e.data);}}
 s.conflicts=(response.conflicts||[]).filter(c=>!adopted.has(c.key));s.lastSync=new Date().toISOString();return s;
}
export function validateBackup(raw){if(!raw||raw.schema!==1||!raw.entities||typeof raw.entities!=='object'||Array.isArray(raw.entities))throw Error('Este archivo no es un respaldo válido del rol.');const s=emptyState();let count=0;for(const [key,e] of Object.entries(raw.entities)){if(++count>20000)throw Error('El respaldo es demasiado grande.');if(!['person','day','month','review'].includes(e.type)||typeof e.id!=='string'||key!==recordKey(e.type,e.id)||!e.data||typeof e.data!=='object')throw Error('Hay datos inválidos en el respaldo.');if(e.type==='person'&&(typeof e.data.name!=='string'||e.data.name.length>120||e.data.id!==e.id))throw Error('Nombre inválido.');if(e.type==='day'){if(!/^\d{4}-\d{2}-\d{2}$/.test(e.id)||!Array.isArray(e.data.masses)||e.data.masses.length>30)throw Error('Día inválido.');for(const m of e.data.masses){if(typeof m.id!=='string'||typeof m.time!=='string'||!Array.isArray(m.personIds)||m.personIds.some(x=>typeof x!=='string')||new Set(m.personIds).size!==m.personIds.length)throw Error('Misa inválida.');}}
 s.entities[key]=clone(e);}
 s.pending=raw.pending&&typeof raw.pending==='object'?clone(raw.pending):{};for(const [key,p] of Object.entries(s.pending))if(!s.entities[key]||p.type!==s.entities[key].type||p.id!==s.entities[key].id)throw Error('Cambio pendiente inválido.');s.history=Array.isArray(raw.history)?raw.history.slice(0,800):[];s.conflicts=[];s.lastSync=raw.lastSync||null;return s;}
export function mergePeople(s,keepId,dropId){if(keepId===dropId)throw Error('Selecciona dos nombres distintos.');const keep=s.entities[recordKey('person',keepId)]?.data;const drop=s.entities[recordKey('person',dropId)]?.data;if(!keep||!drop)throw Error('Nombre no encontrado');for(const d of list(s,'day')){if(d.masses.some(m=>m.personIds.includes(dropId))){const day=clone(d);for(const m of day.masses)m.personIds=[...new Set(m.personIds.map(id=>id===dropId?keepId:id))];change(s,'day',day.date,day,`Unificar ${drop.name} con ${keep.name}`);}}
 change(s,'person',keepId,{...keep,aliases:[...new Set([...(keep.aliases||[]),drop.name,...(drop.aliases||[])])]},`Unificar variantes de ${keep.name}`);change(s,'person',dropId,{...drop,active:false,mergedInto:keepId},`Unificar ${drop.name}`);}
